import React from 'react';
import { cn } from '@/lib/utils';
import { ButtonProps } from './button';

interface ButtonVariantProps extends Omit<ButtonProps, 'variant'> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'destructive';
  size?: 'sm' | 'md' | 'lg';
}

export const ButtonVariant = React.forwardRef<HTMLButtonElement, ButtonVariantProps>(
  ({ className, variant = 'primary', size = 'md', children, ...props }, ref) => {
    const baseClasses = 'inline-flex items-center justify-center rounded-md font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none ring-offset-background';

    const variants = {
      primary: 'bg-primary text-primary-foreground hover:bg-primary/90',
      secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
      outline: 'border border-input hover:bg-accent hover:text-accent-foreground',
      ghost: 'hover:bg-accent hover:text-accent-foreground',
      destructive: 'bg-destructive text-destructive-foreground hover:bg-destructive/90'
    };

    const sizes = {
      sm: 'h-9 px-3 text-sm',
      md: 'h-10 px-4 py-2',
      lg: 'h-11 px-8'
    };

    return (
      <button
        className={cn(
          baseClasses,
          variants[variant],
          sizes[size],
          className
        )}
        ref={ref}
        {...props}
      >
        {children}
      </button>
    );
  }
);

ButtonVariant.displayName = 'ButtonVariant';

# Button Variant Component
A flexible button component that follows the design system with multiple variants and sizes.
## Variants
- **primary**: Main action buttons with brand color - **secondary**: Secondary actions with subtle styling - **outline**: Transparent background with border - **ghost**: Minimal styling for subtle actions - **destructive**: Destructive actions with red styling
## Sizes
- **sm**: Compact for tight spaces (h-9, px-3) - **md**: Standard default size (h-10, px-4) - **lg**: Prominent for important actions (h-11, px-8)
## Usage
```tsx import { ButtonVariant } from '@/components/ui/button-variant';
// Primary button <ButtonVariant variant="primary" size="md"> Save Changes </ButtonVariant>
// Outline button <ButtonVariant variant="outline" size="sm"> Cancel </ButtonVariant>
// Destructive action <ButtonVariant variant="destructive" size="lg"> Delete Item </ButtonVariant> ```
## Accessibility
- Supports keyboard navigation - Proper focus management - Screen reader compatible - High contrast support


import React from 'react';
import { cn } from '@/lib/utils';
import { Card, CardContent, CardFooter, CardHeader } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';

interface ProductCardProps {
  product: {
    id: string;
    name: string;
    price: number;
    image: string;
    category: string;
    rating: number;
    description: string;
  };
  className?: string;
}

export const ProductCard: React.FC<ProductCardProps> = ({ product, className }) => {
  return (
    <Card className={cn('w-full max-w-sm mx-auto', className)}>
      <CardHeader className="p-0">
        <div className="relative aspect-square overflow-hidden rounded-t-lg">
          <img
            src={product.image}
            alt={product.name}
            className="object-cover w-full h-full hover:scale-105 transition-transform duration-300"
          />
          <Badge className="absolute top-2 right-2">
            {product.category}
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="p-4">
        <div className="space-y-2">
          <h3 className="font-semibold text-lg line-clamp-2">
            {product.name}
          </h3>

          <p className="text-sm text-muted-foreground line-clamp-3">
            {product.description}
          </p>

          <div className="flex items-center justify-between">
            <span className="text-2xl font-bold text-primary">
              ${product.price}
            </span>

            <div className="flex items-center space-x-1">
              <span className="text-yellow-500">★</span>
              <span className="text-sm font-medium">
                {product.rating.toFixed(1)}
              </span>
            </div>
          </div>
        </div>
      </CardContent>

      <CardFooter className="p-4 pt-0">
        <Button className="w-full">
          Add to Cart
        </Button>
      </CardFooter>
    </Card>
  );
};


import React from 'react';
import { cn } from '@/lib/utils';
import { ProductCard } from './product-card';

interface ProductGridProps {
  products: any[];
  className?: string;
}

export const ProductGrid: React.FC<ProductGridProps> = ({ products, className }) => {
  return (
    <div className={cn(
      // Mobile: 1 column
      'grid grid-cols-1 gap-4',
      // Tablet: 2 columns
      'sm:grid-cols-2',
      // Desktop: 3 columns
      'lg:grid-cols-3',
      // Large desktop: 4 columns
      'xl:grid-cols-4',
      className
    )}>
      {products.map((product) => (
        <ProductCard key={product.id} product={product} />
      ))}
    </div>
  );
};


/* Responsive breakpoints */
@media (min-width: 640px) {
  .product-card {
    max-width: none;
  }
}

@media (min-width: 768px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .product-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
  }
}

@media (min-width: 1280px) {
  .product-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* Touch-friendly targets */
@media (hover: none) and (pointer: coarse) {
  .button {
    min-height: 44px;
    min-width: 44px;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .hover-scale {
    transform: none !important;
  }
}
